using FamilyVeda.Application.Common;
using FamilyVeda.Application.Portal;
using FamilyVeda.Domain.Common;
using FamilyVeda.Domain.Identity;
using FamilyVeda.Domain.Portal;
using FamilyVeda.Infrastructure.Persistence;
using FamilyVeda.Infrastructure.Portal;
using FluentAssertions;
using Microsoft.EntityFrameworkCore;

namespace FamilyVeda.UnitTests;

public sealed class JoinRequestServiceTests
{
    private static AppDbContext NewDb() =>
        new(new DbContextOptionsBuilder<AppDbContext>().UseInMemoryDatabase(Guid.NewGuid().ToString()).Options);

    private static (UserAccount Head, Family Family) SeedFamily(AppDbContext db, string code = "FV-ABC123")
    {
        var head = new UserAccount { Email = "head@example.invalid", PasswordHash = "x", DisplayName = "Head User", UserType = UserType.FamilyUser };
        var family = new Family { Name = "Test Family", CreatedByUser = head, FamilyCode = code };
        db.AddRange(head, family);
        db.SaveChanges();
        return (head, family);
    }

    [Fact]
    public async Task Create_WithBadCode_Returns404()
    {
        await using var db = NewDb();
        var requester = new UserAccount { Email = "req@example.invalid", PasswordHash = "x", DisplayName = "Requester", UserType = UserType.FamilyUser };
        db.Add(requester);
        await db.SaveChangesAsync();
        var service = new JoinRequestService(db, new StubCurrentUser(requester.Id));

        var act = () => service.CreateAsync(new CreateJoinRequest("FV-NOPE99", "sibling", null), CancellationToken.None);

        await act.Should().ThrowAsync<NotFoundException>();
    }

    [Fact]
    public async Task Create_DuplicatePending_Returns409()
    {
        await using var db = NewDb();
        var (_, family) = SeedFamily(db);
        var requester = new UserAccount { Email = "req@example.invalid", PasswordHash = "x", DisplayName = "Requester", UserType = UserType.FamilyUser };
        db.Add(requester);
        await db.SaveChangesAsync();
        var service = new JoinRequestService(db, new StubCurrentUser(requester.Id));
        await service.CreateAsync(new CreateJoinRequest(family.FamilyCode!, "sibling", null), CancellationToken.None);

        var act = () => service.CreateAsync(new CreateJoinRequest(family.FamilyCode!, "sibling", null), CancellationToken.None);

        await act.Should().ThrowAsync<ConflictException>();
    }

    [Fact]
    public async Task Accept_ByHead_CreatesAdultMember()
    {
        await using var db = NewDb();
        var (head, family) = SeedFamily(db);
        var requester = new UserAccount { Email = "req@example.invalid", PasswordHash = "x", DisplayName = "Requester", UserType = UserType.FamilyUser };
        db.Add(requester);
        await db.SaveChangesAsync();
        var requesterService = new JoinRequestService(db, new StubCurrentUser(requester.Id));
        var created = await requesterService.CreateAsync(new CreateJoinRequest(family.FamilyCode!, "sibling", "hello"), CancellationToken.None);

        var headService = new JoinRequestService(db, new StubCurrentUser(head.Id));
        var result = await headService.AcceptAsync(created.Id, CancellationToken.None);

        result.Status.Should().Be(PortalRequestStatus.Accepted);
        var member = await db.Members.SingleAsync(x => x.UserId == requester.Id);
        member.Role.Should().Be(FamilyRole.AdultMember);
        member.FamilyId.Should().Be(family.Id);
    }

    [Fact]
    public async Task NonHead_CannotListOrAccept_Returns404()
    {
        await using var db = NewDb();
        var (_, family) = SeedFamily(db);
        var requester = new UserAccount { Email = "req@example.invalid", PasswordHash = "x", DisplayName = "Requester", UserType = UserType.FamilyUser };
        var stranger = new UserAccount { Email = "stranger@example.invalid", PasswordHash = "x", DisplayName = "Stranger", UserType = UserType.FamilyUser };
        db.AddRange(requester, stranger);
        await db.SaveChangesAsync();
        var requesterService = new JoinRequestService(db, new StubCurrentUser(requester.Id));
        var created = await requesterService.CreateAsync(new CreateJoinRequest(family.FamilyCode!, "sibling", null), CancellationToken.None);

        var strangerService = new JoinRequestService(db, new StubCurrentUser(stranger.Id));
        var listAct = () => strangerService.GetForFamilyAsync(family.Id, null, CancellationToken.None);
        var acceptAct = () => strangerService.AcceptAsync(created.Id, CancellationToken.None);

        await listAct.Should().ThrowAsync<NotFoundException>();
        await acceptAct.Should().ThrowAsync<NotFoundException>();
    }

    private sealed class StubCurrentUser(Guid userId) : ICurrentUser
    {
        public bool IsAuthenticated => true;
        public Guid UserId => userId;
        public UserType UserType => UserType.FamilyUser;
    }
}
